<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Workspace;
use App\Models\Invitation;
use App\Services\Identity;
use App\Services\Totp;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Facades\Notification;
use Tests\TestCase;
class IdentityTest extends TestCase {
 use RefreshDatabase;
 private function user(): User {return User::factory()->create(['password'=>'test-password-123']);}
 private function business(User $owner): Workspace {$w=Workspace::create(['owner_id'=>$owner->id,'name'=>'Business','type'=>'business']);$w->members()->attach($owner->id,['role'=>'owner']);return $w;}
 private function asUser(User $u): static {return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version]);}
 public function test_login_and_logout(): void {$u=$this->user();$this->post('/login',['email'=>$u->email,'password'=>'test-password-123'])->assertRedirect('/workspaces');$this->assertAuthenticatedAs($u);$this->post('/logout')->assertRedirect('/login');$this->assertGuest();}
 public function test_guest_cannot_access_workspaces(): void {$this->get('/workspaces')->assertRedirect('/login');}
 public function test_private_workspace_even_with_forged_membership(): void {$owner=$this->user();$other=$this->user();$w=Identity::personal($owner);$w->members()->attach($other->id,['role'=>'admin']);$this->asUser($other)->get('/workspaces/'.$w->id)->assertForbidden();$this->post('/workspaces/'.$w->id.'/invitations',['email'=>'x@example.com','role'=>'member'])->assertForbidden();}
 public function test_member_cannot_invite_or_escalate(): void {$o=$this->user();$m=$this->user();$w=$this->business($o);$w->members()->attach($m->id,['role'=>'member']);$this->asUser($m)->post('/workspaces/'.$w->id.'/invitations',['email'=>'x@example.com','role'=>'member'])->assertForbidden();$this->patch('/workspaces/'.$w->id.'/members/'.$m->id,['role'=>'admin'])->assertForbidden();}
 public function test_admin_cannot_grant_admin_or_remove_owner(): void {$o=$this->user();$a=$this->user();$w=$this->business($o);$w->members()->attach($a->id,['role'=>'admin']);$this->asUser($a)->post('/workspaces/'.$w->id.'/invitations',['email'=>'x@example.com','role'=>'admin'])->assertForbidden();$this->delete('/workspaces/'.$w->id.'/members/'.$o->id)->assertForbidden();}
 public function test_invitation_is_single_use_and_email_bound(): void {$o=$this->user();$w=$this->business($o);$token=str_repeat('a',64);Invitation::create(['workspace_id'=>$w->id,'invited_by'=>$o->id,'email'=>'invited@example.com','role'=>'member','token_hash'=>hash('sha256',$token),'expires_at'=>now()->addHour()]);$data=['token'=>$token,'name'=>'Invitee','password'=>'test-password-123','password_confirmation'=>'test-password-123','email'=>'wrong@example.com'];$this->post('/invite',$data)->assertRedirect('/login');$u=User::where('email','invited@example.com')->firstOrFail();$this->assertSame('member',$w->roleFor($u));$this->assertDatabaseMissing('users',['email'=>'wrong@example.com']);$this->post('/invite',$data)->assertNotFound();}
 public function test_expired_invitation_denied(): void {$o=$this->user();$w=$this->business($o);$token=str_repeat('b',64);Invitation::create(['workspace_id'=>$w->id,'invited_by'=>$o->id,'email'=>'expired@example.com','role'=>'member','token_hash'=>hash('sha256',$token),'expires_at'=>now()->subHour()]);$this->post('/invite',['token'=>$token])->assertNotFound();}
 public function test_two_factor_blocks_password_only_and_recovery_is_single_use(): void {$u=$this->user();$u->forceFill(['two_factor_secret'=>Totp::secret(),'recovery_codes'=>[Hash::make('abcdef1234567890')]])->save();$this->post('/login',['email'=>$u->email,'password'=>'test-password-123'])->assertRedirect('/two-factor-challenge');$this->assertGuest();$this->get('/workspaces')->assertRedirect('/login');$this->post('/two-factor-challenge',['code'=>'abcdef1234567890'])->assertRedirect('/workspaces');$this->assertAuthenticatedAs($u);$this->assertFalse(Totp::consume($u,'abcdef1234567890'));}
 public function test_totp_known_vector_and_replay(): void {$this->assertSame('287082',Totp::code('GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ',1));$this->travelTo(\Illuminate\Support\Carbon::parse('2026-01-01 00:00:15 UTC'));$u=$this->user();$secret=Totp::secret();$u->forceFill(['two_factor_secret'=>$secret])->save();$this->assertSame(0,$u->auth_version);$code=Totp::code($secret,intdiv(now()->timestamp,30));$this->assertTrue(Totp::consume($u,$code));$this->assertFalse(Totp::consume($u,$code));}
 public function test_stale_session_revoked(): void {$u=$this->user();$this->actingAs($u)->withSession(['auth_version'=>-1])->get('/workspaces')->assertRedirect('/login');$this->assertGuest();}
 public function test_cross_workspace_invitation_revocation_denied(): void {$o=$this->user();$other=$this->user();$w=$this->business($o);$foreign=$this->business($other);$i=Invitation::create(['workspace_id'=>$foreign->id,'invited_by'=>$other->id,'email'=>'x@example.com','role'=>'member','token_hash'=>hash('sha256','x'),'expires_at'=>now()->addHour()]);$this->asUser($o)->delete('/workspaces/'.$w->id.'/invitations/'.$i->id)->assertNotFound();}
 public function test_forged_business_owner_role_is_denied(): void {$o=$this->user();$m=$this->user();$w=$this->business($o);$w->members()->attach($m->id,['role'=>'owner']);$this->asUser($m)->get('/workspaces/'.$w->id)->assertForbidden();}
 public function test_authenticated_login_redirects_to_workspace(): void {$u=$this->user();$this->asUser($u)->get('/login')->assertRedirect('/workspaces');}
 public function test_removed_member_cannot_reuse_outstanding_invitation(): void {$o=$this->user();$m=$this->user();$w=$this->business($o);$w->members()->attach($m->id,['role'=>'member']);$token=str_repeat('c',64);$i=Invitation::create(['workspace_id'=>$w->id,'invited_by'=>$o->id,'email'=>$m->email,'role'=>'member','token_hash'=>hash('sha256',$token),'expires_at'=>now()->addHour()]);$this->asUser($o)->delete('/workspaces/'.$w->id.'/members/'.$m->id)->assertRedirect();$this->assertNotNull($i->fresh()->revoked_at);$this->asUser($m)->post('/invite',['token'=>$token])->assertNotFound();}
 public function test_expired_two_factor_enrollment_denied(): void {$u=$this->user();$secret=Totp::secret();$this->asUser($u)->withSession(['enroll_secret'=>$secret,'enroll_expires'=>time()-1])->post('/profile/2fa/confirm',['password'=>'test-password-123','code'=>Totp::code($secret,intdiv(time(),30))])->assertForbidden();$this->assertNull($u->fresh()->two_factor_secret);}
 public function test_totp_rejects_stale_account_version(): void {$u=$this->user();$secret=Totp::secret();$u->forceFill(['two_factor_secret'=>$secret])->save();User::whereKey($u->id)->update(['auth_version'=>1]);$this->assertFalse(Totp::consume($u,Totp::code($secret,intdiv(now()->timestamp,30))));}
 public function test_login_rejects_multibyte_password_over_bcrypt_limit(): void {$u=$this->user();$this->post('/login',['email'=>$u->email,'password'=>str_repeat('é',40)])->assertSessionHasErrors('password');$this->assertGuest();}
}
